        for vector in vectorInputs {
            mismatches.check(
                portRepeatingBlockI16(
                    vector.simd[0],
                    vector.simd[1],
                    vector.simd[2],
                    vector.simd[3],
                    vector.simd[4],
                    vector.simd[5],
                    vector.simd[6],
                    vector.simd[7]
                ),
                highwayRepeatingBlockI16(
                    vector.simd[0],
